parameters.jsCode:
const dd = $('Direct Data · Cadastro PJ Plus').item.json.retorno ?? {};
const f = $('Buscar Fornecedor').item.json;
const end = (dd.enderecos && dd.enderecos[0]) || {};

function classificarRegime(r) {
  const mei = (r.opcaoMEI || '').toString().toUpperCase();
  const simples = (r.opcaoSimples || '').toString().toUpperCase();
  if (mei === 'SIM' || mei === 'S' || r.opcaoMEI === true) return 'MEI';
  if (simples === 'SIM' || simples === 'S' || r.opcaoSimples === true) return 'Simples Nacional (padrão)';
  const trib = (r.tributacao || '').toLowerCase();
  if (trib.includes('real')) return 'Lucro Real (regime regular IBS/CBS)';
  if (trib.includes('presumido')) return 'Lucro Presumido';
  if (trib.includes('imune') || trib.includes('isento')) return 'Imune/Isento/Não contribuinte';
  return 'ND';
}

function extrairFaturamento(r) {
  const raw = r.faturamentoPresumido;
  if (!raw) return null;
  let s = String(raw).replace(/[^\d,.-]/g, '');
  if (s.includes(',')) {
    s = s.replace(/\./g, '').replace(',', '.');
  }
  const valor = parseFloat(s);
  return Number.isFinite(valor) ? valor : null;
}

return [{
  json: {
    fornecedor_id: f.fornecedor_id,
    razao_social: dd.razaoSocial ?? f.razao_social ?? null,
    nome_fantasia: dd.nomeFantasia ?? null,
    uf: end.uf ?? f.uf ?? null,
    cidade: end.cidade ?? f.cidade ?? null,
    regime_tributario: classificarRegime(dd),
    porte: dd.porte ?? null,
    faturamento_estimado: extrairFaturamento(dd)
  }
}];

